javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {

    if (event.name == 'NOW_RECORD_LIST_CONNECTED#WRAPPED_CLICKED' &&
        event.payload.wrappedAction == 'CREATE_NEW_RECORD') {
        const isConfigContext = api.context.props.nowUxfParentPageComponentId !== undefined;
        const isAceNav = api.context.props.aceNav !== undefined;

        if (!["instance", "clone_profile"].includes(event.payload.wrappedPayload.fields.table) && isConfigContext) {

            return {
                modalId: "[component-id$='modal_viewport_2']",
                headerLabel: null,
                showModal: true,
                preserveState: false,
                displayOptions: null,
                bare: true,
                viewportElementId: "viewport_1",
                viewportRoute: "clone_record",
                viewportFields: {
                    ...event.payload.wrappedPayload.fields, // Spread existing fields
                    sysId: -1 // Just -1 for new record
                },
                viewportParams: {
                    ...event.payload.wrappedPayload.params, // Spread existing params
                    view: 'clone_ui',
                    aceNav: api.context.props.aceNav,
                    mode: 'create',
                    t: Date.now() // Force refresh
                }
            };
        }
    }
})

